 CHECK(((substr(source_hash,1) NOT GLOB '*[^0-9a-f]*' AND length(substr(source_hash,1))>=64 AND length(substr(source_hash,1))<=64)))
);
CREATE TABLE IF NOT EXISTS "b_public__course_lessons" (
 "id" TEXT NOT NULL,
 "module_id" TEXT NOT NULL,
 "source_heading" TEXT NOT NULL,
 "title" TEXT NOT NULL,
 "summary" TEXT NOT NULL,
 "status" TEXT NOT NULL,
 "sort_order" INTEGER NOT NULL,
 "version" INTEGER NOT NULL,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 PRIMARY KEY("id"),
 FOREIGN KEY(module_id) REFERENCES "b_public__course_modules"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
 CHECK((sort_order >= 0)),
 CHECK(((version >= 1) AND (version <= 2147483647)))
);
CREATE TABLE IF NOT EXISTS "b_public__course_modules" (
 "id" TEXT NOT NULL,
 "chapter_id" TEXT NOT NULL,
 "source_number" INTEGER NOT NULL,
 "title" TEXT NOT NULL,
 "objective" TEXT NOT NULL,
 "duration" TEXT NOT NULL,
 "status" TEXT NOT NULL,
