 "version" INTEGER NOT NULL,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 PRIMARY KEY("id"),
 FOREIGN KEY(chapter_id) REFERENCES "b_public__course_chapters"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
 CHECK((sort_order >= 0)),
 CHECK(((source_number >= 1) AND (source_number <= 16))),
 CHECK(((version >= 1) AND (version <= 2147483647)))
);
CREATE TABLE IF NOT EXISTS "b_public__course_notes" (
 "id" TEXT NOT NULL,
 "course_id" TEXT NOT NULL,
 "lesson_id" TEXT,
 "author_id" TEXT NOT NULL,
 "content_json" TEXT NOT NULL,
 "position_json" TEXT NOT NULL,
 "pinned" INTEGER NOT NULL,
 "version" INTEGER NOT NULL,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 PRIMARY KEY("id"),
 FOREIGN KEY(course_id) REFERENCES "b_public__courses"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(lesson_id) REFERENCES "b_public__course_lessons"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
 CHECK((((lesson_id IS NOT NULL) AND pinned) OR (NOT pinned))),
 CHECK((json_type(position_json) = 'object')),
 CHECK(((version >= 1) AND (version <= 2147483647)))
);
CREATE TABLE IF NOT EXISTS "b_public__course_revisions" (
 "id" TEXT NOT NULL,
