 FOREIGN KEY(source_revision_id) REFERENCES "b_public__course_revisions"(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 CHECK((action IN ('edit', 'create', 'delete', 'undo', 'redo')))
);
